import asyncio

import httpx
from src.config import settings

class PaymentGatewayClient:
    def __init__(self):
        self.base_url = settings.payment_api_url
        self.api_key = settings.payment_api_key
        self._order_locks = {}
        self._successful_charges = {}

    async def charge(self, order_id: str, amount: float, idempotency_key: str) -> dict:
        # Payment idempotency belongs to the order, not to an individual HTTP
        # request. This key remains stable when a caller retries with a new key.
        payment_key = f"order:{order_id}"
        lock = self._order_locks.setdefault(order_id, asyncio.Lock())

        async with lock:
            previous_result = self._successful_charges.get(order_id)
            if previous_result is not None:
                return previous_result

            headers = {
                "Authorization": f"Bearer {self.api_key}",
                "Idempotency-Key": payment_key
            }

            for attempt in range(settings.max_retries + 1):
                try:
                    async with httpx.AsyncClient() as client:
                        resp = await client.post(
                            f"{self.base_url}/charges",
                            json={"order_id": order_id, "amount": amount},
                            headers=headers,
                            timeout=2.0
                        )
                except httpx.RequestError as exc:
                    if attempt == settings.max_retries:
                        raise RuntimeError("Gateway unreachable") from exc
                    continue

                if resp.status_code == 200:
                    result = resp.json()
                    if result.get("status", "SUCCESS") == "SUCCESS":
                        self._successful_charges[order_id] = result
                    return result
                if resp.status_code == 400:
                    return {"status": "FAILED", "reason": "Bad Request"}
                if attempt == settings.max_retries:
                    raise RuntimeError("Gateway unavailable")

    def verify_webhook_signature(self, signature: str, payload_bytes: bytes) -> bool:
        """
        Defect #5: Timing Attack / Insecure Direct String Comparison.
        Uses raw == equality instead of constant-time hmac.compare_digest.
        """
        expected_sig = "sig_" + str(len(payload_bytes))
        return signature == expected_sig

